]],["valid_from",["timestamp with time zone"]],["valid_to",["timestamp with time zone"]],["source_reference",["text"]]]},{"name":"public.tenant_ediel_profiles","owner":"postgres","columns":[["id",["uuid"]],["company_id",["uuid"]],["environment",["text"]],["market",["text"]],["is_enabled",["boolean"]],["valid_from",["timestamp with time zone"]],["valid_to",["timestamp with time zone"]],["metadata",["jsonb"]]]},{"name":"public.user_permission_overrides","owner":"postgres","columns":[["id",["uuid"]],["company_id",["uuid"]],["user_id",["uuid"]],["permission_key",["text"]],["effect",["text"]],["reason",["text"]],["valid_from",["timestamp with time zone"]],["valid_to",["timestamp with time zone"]],["is_active",["boolean"]],["created_at",["timestamp with time zone"]],["updated_at",["timestamp with time zone"]],["created_by",["uuid"]],["updated_by",["uuid"]]]},{"name":"public.user_permissions","owner":"postgres","columns":[["id",["uuid"]],["user_id",["uuid"]],["company_id",["uuid"]],["permission_id",["uuid"]],["permission_key",["text"]],["effect",["text"]],["status",["text"]],["is_active",["boolean"]],["created_at",["timestamp with time zone"]],["updated_at",["timestamp with time zone"]]]},{"name":"public.user_profiles","owner":"postgres","columns":[["id",["uuid"]],["email",["text"]],["full_name",["text"]],["created_at",["timestamp with time zone"]],["updated_at",["timestamp with time zone"]],["user_status",["text"]],["auth_email_confirmed_at",["timestamp with time zone"]],["auth_last_sign_in_at",["timestamp with time zone"]],["auth_last_synced_at",["timestamp with time zone"]],["last_invite_sent_at",["timestamp with time zone"]],["last_password_reset_sent_at",["timestamp with time zone"]],["last_confirmation_email_sent_at",["timestamp with time zone"]],["last_auth_email_action",["text"]],["last_auth_email_action_at",["timestamp with time zone"]],["last_auth_email_action_by",["uuid"]],["last_auth_email_message",["text"]]]},{"name":"public.user_roles","owner":"postgres","columns":[["id",["uuid"]],["user_id",["uuid"]],["company_id",["uuid"]],["role",["text"]],["role_id",["uuid"]],["status",["text"]],["is_active",["boolean"]],["created_at",["timestamp with time zone"]],["updated_at",["timestamp with time zone"]]]}]$relations$::jsonb;
 lock_relations CONSTANT jsonb := $lock_relations$[{"name":"auth.users","owner":"supabase_auth_admin"},{"name":"gridex_received_sources.permission_transitions","owner":"postgres"},{"name":"gridex_service_administration.scope_versions","owner":"postgres"},{"name":"gridex_utilts_binding.contracts","owner":"postgres"},{"name":"gridex_utilts_binding.receipts","owner":"postgres"},{"name":"public.ediel_ack_transaction_results","owner":"postgres"},{"name":"public.ediel_assignment_permission_links","owner":"postgres"},{"name":"public.ediel_data_access_grants","owner":"postgres"},{"name":"public.ediel_service_assignments","owner":"postgres"},{"name":"public.ediel_service_evidence","owner":"postgres"},{"name":"public.meter_reading_series","owner":"postgres"},{"name":"public.metering_permission_sites","owner":"postgres"},{"name":"public.metering_permissions","owner":"postgres"},{"name":"public.tenant_counterparty_relations","owner":"postgres"}]$lock_relations$::jsonb;
 target_names text[];x jsonb;col jsonb;f record;r record;n integer;missing integer:=0;allow_absent boolean:=true;
 actual_acl jsonb;defaults_profile jsonb;before_catalog jsonb;after_catalog jsonb;
BEGIN
 PERFORM set_config('search_path','pg_catalog',true);
 PERFORM set_config('check_function_bodies','on',true);
 PERFORM set_config('lock_timeout','5s',true);
 PERFORM set_config('statement_timeout','60s',true);
 IF current_user<>'postgres' OR session_user<>'postgres' OR current_setting('server_version_num')::integer NOT BETWEEN 170000 AND 179999
 OR current_setting('check_function_bodies')<>'on' THEN RAISE EXCEPTION 'sql20_existing_pg17_postgres_context_required' USING ERRCODE='42501';END IF;
 SELECT array_agg(value->>'name' ORDER BY value->>'name') INTO target_names FROM jsonb_array_elements(profiles) WHERE(value->>'target')::boolean;
 IF cardinality(target_names)<>25 OR jsonb_array_length(profiles)<>103 OR jsonb_array_length(relations)<>97 THEN RAISE EXCEPTION 'sql20_exact_closed_scope_required';END IF;
 IF EXISTS(SELECT FROM unnest(ARRAY['gridex_bilateral_prodat','gridex_received_sources','gridex_supply_rescission','public'])v(name) LEFT JOIN pg_namespace ns ON ns.nspname=v.name
  WHERE ns.oid IS NULL OR ns.nspowner IS DISTINCT FROM to_regrole(CASE WHEN v.name='public' THEN 'pg_database_owner' ELSE 'postgres' END)::oid OR NOT has_schema_privilege('postgres',ns.oid,'USAGE') OR NOT has_schema_privilege('postgres',ns.oid,'CREATE')
   OR has_schema_privilege('anon',ns.oid,'CREATE') OR has_schema_privilege('authenticated',ns.oid,'CREATE') OR has_schema_privilege('service_role',ns.oid,'CREATE'))
 THEN RAISE EXCEPTION 'sql20_existing_creator_namespace_required' USING ERRCODE='42501';END IF;
 -- The measured public default grants service_role. It is compatible with
 -- the final public endpoint ACL, never permission to edit the default policy.
 IF EXISTS(SELECT FROM pg_default_acl d LEFT JOIN pg_namespace ns ON ns.oid=d.defaclnamespace WHERE d.defaclrole='postgres'::regrole AND d.defaclobjtype='f'
  AND(d.defaclnamespace=0 OR ns.nspname IN('gridex_bilateral_prodat','gridex_received_sources','gridex_supply_rescission')))
 THEN RAISE EXCEPTION 'sql20_known_private_creation_defaults_required' USING ERRCODE='42501';END IF;
 SELECT jsonb_agg(jsonb_build_object('grantee',a.grantee::regrole::text,'grantor',a.grantor::regrole::text,'privilege',a.privilege_type,'grantable',a.is_grantable)ORDER BY a.grantee::regrole::text,a.privilege_type,a.is_grantable) INTO defaults_profile
 FROM pg_default_acl d JOIN pg_namespace ns ON ns.oid=d.defaclnamespace CROSS JOIN LATERAL aclexplode(d.defaclacl)a WHERE d.defaclrole='postgres'::regrole AND d.defaclobjtype='f' AND ns.nspname='public';
 IF defaults_profile IS NOT NULL AND defaults_profile IS DISTINCT FROM '[{"grantee":"postgres","grantor":"postgres","privilege":"EXECUTE","grantable":false},{"grantee":"service_role","grantor":"postgres","privilege":"EXECUTE","grantable":false}]'::jsonb
 THEN RAISE EXCEPTION 'sql20_known_public_creation_defaults_required' USING ERRCODE='42501';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(profiles) LOOP

  SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace s ON s.oid=p.pronamespace WHERE s.nspname||'.'||p.proname=x->>'name';
  IF allow_absent AND (x->>'target')::boolean AND n=0 THEN missing:=missing+1;CONTINUE;END IF;
  IF n<>1 THEN RAISE EXCEPTION 'sql20_exact_single_interface_required:%',x->>'name' USING ERRCODE='55000';END IF;
  SELECT p.*,l.lanname INTO f FROM pg_proc p JOIN pg_language l ON l.oid=p.prolang WHERE p.oid=to_regprocedure(x->>'signature');
  IF NOT FOUND OR f.proowner IS DISTINCT FROM to_regrole(x->>'owner')::oid OR f.prokind<>'f' OR f.lanname IS DISTINCT FROM x->>'language'
   OR f.pronargs<>(x->>'argumentCount')::integer OR coalesce(to_jsonb(f.proargnames),'null'::jsonb) IS DISTINCT FROM x->'argumentNames'
   OR f.proargmodes IS NOT NULL OR f.proallargtypes IS NOT NULL OR f.pronargdefaults<>(CASE WHEN x->>'defaultExpression' IS NULL THEN 0 ELSE 1 END)
   OR pg_get_expr(f.proargdefaults,0) IS DISTINCT FROM x->>'defaultExpression'
   OR f.prorettype IS DISTINCT FROM to_regtype(x->>'returnType')::oid OR f.prosecdef IS DISTINCT FROM (x->>'securityDefiner')::boolean
   OR f.provolatile::text IS DISTINCT FROM x->>'volatility' OR f.proparallel<>'u' OR f.proisstrict IS DISTINCT FROM (x->>'strict')::boolean
   OR f.proleakproof OR f.proretset OR f.procost<>100 OR f.prorows<>0 OR f.provariadic::oid<>0 OR f.prosupport::oid<>0
   OR f.protrftypes IS NOT NULL OR f.probin IS NOT NULL OR f.prosqlbody IS NOT NULL OR coalesce(to_jsonb(f.proconfig),'null'::jsonb) IS DISTINCT FROM x->'config'
   OR encode(sha256(convert_to(f.prosrc,'UTF8')),'hex') IS DISTINCT FROM x->>'sha256'
   OR has_function_privilege('postgres',f.oid,'EXECUTE') IS DISTINCT FROM (x->>'runnerExecute')::boolean
  THEN RAISE EXCEPTION 'sql20_exact_function_profile_required:%',x->>'name' USING ERRCODE='55000';END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('grantor',a.grantor::regrole::text,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,'privilege',a.privilege_type,'grantable',a.is_grantable)
   ORDER BY CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE a.grantee::regrole::text END,a.grantor::regrole::text,a.privilege_type,a.is_grantable),'[]') INTO actual_acl FROM aclexplode(coalesce(f.proacl,acldefault('f',f.proowner))) a;
  IF actual_acl IS DISTINCT FROM x->'acl' THEN RAISE EXCEPTION 'sql20_exact_function_acl_required:%',x->>'name' USING ERRCODE='55000';END IF;

 END LOOP;
 IF missing NOT IN(0,25) THEN RAISE EXCEPTION 'sql20_uniform_absent_or_exact_cluster_required' USING ERRCODE='55000';END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(relations) LOOP
  SELECT c.* INTO r FROM pg_class c WHERE c.oid=to_regclass(x->>'name');
  IF NOT FOUND OR r.relkind<>'r' OR r.relowner IS DISTINCT FROM to_regrole(x->>'owner')::oid OR NOT has_table_privilege('postgres',r.oid,'SELECT') THEN RAISE EXCEPTION 'sql20_existing_typed_relation_required:%',x->>'name' USING ERRCODE='55000';END IF;
  FOR col IN SELECT value FROM jsonb_array_elements(x->'columns') LOOP
   IF NOT EXISTS(SELECT FROM pg_attribute a WHERE a.attrelid=r.oid AND a.attnum>0 AND NOT a.attisdropped AND a.attname=col->>0 AND to_jsonb(format_type(a.atttypid,a.atttypmod)) IN(SELECT value FROM jsonb_array_elements(col->1)))
   THEN RAISE EXCEPTION 'sql20_known_named_column_type_required:%.%',x->>'name',col->>0 USING ERRCODE='55000';END IF;
  END LOOP;
 END LOOP;
 -- Existing comma-list LOCK-only dependencies supplement the literal97
 -- named-column boundary. SHARE requires UPDATE, DELETE or TRUNCATE.
 FOR x IN SELECT value FROM jsonb_array_elements(lock_relations) LOOP
  SELECT c.* INTO r FROM pg_class c WHERE c.oid=to_regclass(x->>'name');
  IF NOT FOUND OR r.relkind<>'r' OR r.relowner IS DISTINCT FROM to_regrole(x->>'owner')::oid
   OR NOT has_schema_privilege('postgres',r.relnamespace,'USAGE') OR NOT has_table_privilege('postgres',r.oid,'UPDATE,DELETE,TRUNCATE')
  THEN RAISE EXCEPTION 'sql20_existing_share_lock_relation_required:%',x->>'name' USING ERRCODE='55000';END IF;
 END LOOP;
 -- Fully qualified complete POST is a true zero-DDL no-op, preserving xmin.
